<script>
(() => {
  'use strict';
  var page = 0;
  var token = null;
  var busy = false;
  var q = function (selector) { return document.querySelector(selector); };
  var qa = function (selector) { return Array.from(document.querySelectorAll(selector)); };

  function api() {
    return window.MistportOpening || (window.parent && window.parent.MistportOpening) || null;
  }

  function note(text, kind) {
    var el = q('#status');
    el.textContent = text;
    el.className = 'status' + (kind ? ' ' + kind : '');
  }

  function selected(name) {
    var el = q('input[name="' + name + '"]:checked');
    return el ? el.value : '';
  }

  function draft() {
    return {
      name: q('#name').value,
      background: selected('background'),
      skill: selected('skill'),
      approach: q('#approach').value,
      route: selected('route'),
      custom_goal: q('#customGoal').value,
    };
  }

  function validateBasics(includeRoute) {
    var d = draft();
    if (!d.name.trim()) throw new Error('请填写玩家称呼');
    if (!d.background) throw new Error('请选择玩家来历');
    if (!d.skill) throw new Error('请选择玩家专长');
    if (!d.approach) throw new Error('请选择行事倾向');
    if (includeRoute && !d.route) throw new Error('请选择开局路线');
    if (includeRoute && d.route === 'custom' && d.custom_goal.trim().length < 4) throw new Error('请把自定义来意写得再具体一点');
    return d;
  }

  function showPage(next) {
    page = Math.max(0, Math.min(2, next));
    qa('.section').forEach(function (el) { el.classList.toggle('on', Number(el.dataset.page) === page); });
    qa('.step').forEach(function (el) { el.classList.toggle('on', Number(el.dataset.step) === page); });
    q('#back').disabled = page === 0 || busy;
    q('#next').textContent = page === 2 ? (token ? '确认并进入' : '生成预览') : '继续';
    q('#next').disabled = busy;
  }

  function invalidatePreview() {
    token = null;
    q('#summary').hidden = true;
    if (page === 2) q('#next').textContent = '生成预览';
    note('表单已变化，需要重新生成预览。');
  }

  async function makePreview() {
    var provider = api();
    if (!provider) throw new Error('开场协调器未启用');
    var result = await provider.prepare(validateBasics(true));
    token = result.token;
    q('#sumTitle').textContent = result.preview.title;
    q('#sumProfile').textContent = result.preview.profile;
    q('#sumRoute').textContent = result.preview.route;
    q('#sumImpact').textContent = result.preview.impact;
    q('#sumProtocol').textContent = result.preview.fixed_greeting
      ? '切换到对应固定 Greeting，写入该 Swipe 初态并保存；不会自动替玩家发言。'
      : '重写动态 Greeting，发送预览中的 canonical 玩家开局消息，触发正常 AI 回复并等待 MVU 楼层快照。';
    q('#summary').hidden = false;
    q('#next').textContent = '确认并进入';
    note('预览已冻结。再次修改任何字段都会使本次预览失效。', 'ok');
  }

  async function doCommit() {
    var provider = api();
    if (!provider) throw new Error('开场协调器未启用');
    busy = true;
    showPage(page);
    note('正在写入玩家档案、目标 Swipe 初态并等待保存……');
    var result = await provider.commit(token, validateBasics(true));
    if (document.body && document.body.isConnected) {
      note(result.status === 'awaiting_ai' ? '玩家消息已保存，等待你手动继续生成。' : '提交完成。', result.status === 'awaiting_ai' ? 'bad' : 'ok');
    }
  }

  q('#back').addEventListener('click', function () { if (!busy) showPage(page - 1); });
  q('#next').addEventListener('click', async function () {
    if (busy) return;
    try {
      if (page === 0) { showPage(1); return; }
      if (page === 1) { validateBasics(false); showPage(2); return; }
      if (!token) await makePreview();
      else await doCommit();
    } catch (error) {
      busy = false;
      showPage(page);
      note(error.message || String(error), 'bad');
    }
  });

  qa('input,textarea,select').forEach(function (el) {
    el.addEventListener('input', function () {
      if (token) invalidatePreview();
      if (el.name === 'route') q('#custom').classList.toggle('on', selected('route') === 'custom');
    });
    el.addEventListener('change', function () {
      if (token) invalidatePreview();
      if (el.name === 'route') q('#custom').classList.toggle('on', selected('route') === 'custom');
    });
  });

  if (!api()) {
    q('#fallback').classList.add('on');
    note('协调器缺失：当前只能阅读说明或手动切换固定 Greeting。', 'bad');
  }
  showPage(0);
})();
</script>
</body>
</html>
