ock;color:var(--muted);margin-top:2px}.memo{display:grid;grid-template-columns:1fr auto;gap:7px;margin-top:8px}.memo input{min-width:0;border:1px solid #4d7887;border-radius:9px;background:#0a2027;color:var(--ink);padding:8px 10px;font:inherit}.memo button{text-align:center;font-weight:800}.foot{display:flex;gap:9px;align-items:center;padding:0 12px 12px;color:var(--muted);font-size:11px}.foot .error{color:var(--red)}.foot .ok{color:var(--green)}.foot button{margin-left:auto;border:0;background:transparent;color:var(--cyan);cursor:pointer;font:inherit}.busy{opacity:.55;pointer-events:none}
@media(max-width:780px){.top{grid-template-columns:repeat(3,1fr)}.middle{grid-template-columns:1fr 1fr}.middle .panel:first-child{grid-column:1/-1}.actions{grid-template-columns:1fr}.memo{grid-template-columns:1fr}.head{padding:11px}.body{padding:9px}}
@media(max-width:420px){body{padding:6px}.top{grid-template-columns:1fr 1fr}.middle{grid-template-columns:1fr}.middle .panel:first-child{grid-column:auto}.live{display:none}}
</style>
</head>
<body>
<main class="app">
  <header class="head">
    <div><h1>雾港航站·当楼运行面板</h1><div id="identity" class="sub">正在连接当前消息楼层……</div></div>
    <span id="live" class="live">读取中</span>
  </header>
  <div id="body" class="body">
    <section class="top">
      <div class="cell"><div class="label">区域</div><div id="area" class="value">—</div></div>
      <div class="cell"><div class="label">天气</div><div id="weather" class="value">—</div></div>
      <div class="cell"><div class="label">时段</div><div id="phase" class="value">—</div></div>
      <div class="cell"><div class="label">潮位</div><div id="tide" class="value">—</div></div>
      <div class="cell"><div class="label">航站安全</div><div id="safety" class="value">—</div></div>
      <div class="cell"><div class="label">体力</div><div id="stamina" class="value">—</div><div class="bar"><i id="staminaBar"></i></div></div>
    </section>

    <section class="middle">
      <article class="panel"><h2>当前主线</h2><div id="task" class="task">—</div><div id="taskStage" class="detail">—</div><div id="route" class="detail">—</div></article>
      <article class="panel"><h2>关系与时限</h2><div class="detail">洛檀信任：<b id="trust">—</b></div><div class="detail">雾钟倒计时：<b id="countdown">—</b></div><div class="detail">警报：<b id="alert">—</b></div></article>
      <article class="panel"><h2>物资</h2><div id="supplies" class="chips"></div></article>
    </section>

    <section class="middle">
      <article class="panel"><h2>已知线索</h2><div id="clues" class="chips"></div></article>
      <article class="panel"><h2>玩家公开起点</h2><div id="player" class="detail">—</div></article>
      <article class="panel"><h2>本楼玩家手记</h2><div id="memoRead" class="detail">—</div></article>
    </section>

    <section id="actions" class="actions">
      <button data-index="0"><b>读取中</b><small>等待当前任务</small></button>
      <button data-index="1"><b>读取中</b><small>等待当前区域</small></button>
      <button data-index="2"><b>读取中</b><small>等待当前线索</small></button>
    </section>

    <section class="memo">
      <input id="memoInput" maxlength="80" placeholder="写一条只属于本楼快照的玩家手记">
      <button id="saveMemo">保存本楼手记</button>
    </section>
  </div>
  <footer class="foot"><span id="status">初始化中……</span><button id="retry">重新读取</button></footer>
</main>
<script>
(() => {
  'use strict';
  var q = function (id) { return document.getElementById(id); };
  var stops = [];
  var messageId = null;
  var swipeId = null;
  var state = null;
  var suggestions = [];

  function runtime() {
    return window.MistportRuntime || (window.parent && window.parent.MistportRuntime) || null;
  }

  function note(text, kind) {
    q('status').textContent = text;
    q('status').className = kind || '';
  }

  function timeout(ms) {
    return new Promise(function (_resolve, reject) {
      setTimeout(function () { reject(new Error('等待 MVU 超时（' + ms + 'ms）')); }, ms);
    });
  }

  function text(value, fallback) {
    return value == null || value === '' ? (fallback || '未记录') : String(value);
  }

  function readState() {
    var data = Mvu.getMvuData({ type: 'message', message_id: messageId });
    if (!data || !data.stat_data) throw new Error('本楼没有 MVU 快照');
    return data.stat_data;
  }

  function renderChips(id, value, warning) {
    var box = q(id);
    box.textContent = '';
    var entries = [];
    if (Array.isArray(value)) entries = value.filter(function (item) {
      return !(item && typeof item === 'object' && item.$arrayMeta === true);
    }).map(function (item) { return [String(item), null]; });
    else if (value && typeof value === 'object') entries = Object.keys(value).filter(function (key) {
      return !key.startsWith('$');
    }).map(function (key) { return [key, value[key]]; });
    if (!entries.length) {
      var empty = document.createElement('span');
      empty.className = 'empty';
      empty.textContent = '暂无';
      box.appendChild(empty);
      return;
    }
    entries.forEach(function (entry) {
      var chip = document.createElement('span');
      chip.className = 'chip' + (warning ? ' warn' : '');
      chip.textContent = entry[1] == null ? entry[0] : entry[0] + '×' + String(entry[1]);
      box.appendChild(chip);
    });
  }

  function buildSuggestions(s) {
    var task = text(s.角色 && s.角色.当前任务, '处理航站事务');
    var area = text(s.世界 && s.世界.区域, '当前区域');
    var clues = Array.isArray(s.线索) ? s.线索 : [];
    if (task.indexOf('灯标') >= 0) {
      return [
        { title: '先查备用件', detail: '从物资闭环入手', text: '我先去仓库核对备用保险丝和灯油，再决定是否上栈桥。' },
        { title: '观察灯闪规律', detail: '从环境证据入手', text: '我留在安全位置观察灯标闪烁的间隔，并和雾钟声对照。' },
        { title: '问洛檀前两晚', detail: '从人物信息入手', text: '我请洛檀把前两晚灯标异常的时间、天气和她做过的处理说清楚。' },
      ];
    }
    if (task.indexOf('渡船') >= 0) {
      return [
        { title: '辨认雾钟方向', detail: '先确认声音是否可信', text: '我到栈桥尽头辨认雾钟方向，同时记录潮流和风向。' },
        { title: '查末班记录', detail: '确认船员与载货', text: '我先查末班渡船的登记、电报和预定靠岸时间。' },
        { title: '准备救援物资', detail: '为失败情境留余地', text: '我清点绳索、风灯和保暖毯，按最坏情况准备接应。' },
      ];
    }
    return [
      { title: '问值班异常', detail: '让世界主动提供压力', text: '我问洛檀今晚的值班记录里，哪一项最不符合往常。' },
      { title: '查看当前区域', detail: area, text: '我先不急着表态，仔细观察' + area + '里正在发生的事。' },
      { title: clues.length ? '追查最新线索' : '确认下一班时刻', detail: clues.length ? String(clues[clues.length - 1]) : '避免错过时间窗口', text: clues.length ? '我从最新线索“' + String(clues[clues.length - 1]) + '”继续查下去。' : '我确认下一班渡船、换班和潮位变化的准确时间。' },
    ];
  }

  function render(s) {
    state = s;
    q('area').textContent = text(s.世界 && s.世界.区域);
    q('weather').textContent = text(s.世界 && s.世界.天气);
    q('phase').textContent = text(s.世界 && s.世界.时段);
    q('tide').textContent = text(s.世界 && s.世界.潮位);
    q('safety').textContent = text(s.系统 && s.系统.航站安全度);
    var stamina = Math.max(0, Math.min(100, Number(s.角色 && s.角色.体力) || 0));
    q('stamina').textContent = String(Math.round(stamina));
    q('staminaBar').style.width = stamina + '%';
    q('task').textContent = text(s.任务 && s.任务.主线 && s.任务.主线.名称, text(s.角色 && s.角色.当前任务));
    q('taskStage').textContent = '阶段：' + text(s.任务 && s.任务.主线 && s.任务.主线.阶段);
    q('route').textContent = '路线：' + text(s.系统 && s.系统.路线);
    q('trust').textContent = text(s.关系 && s.关系.洛檀信任);
    var countdown = s.系统 && s.系统.雾钟倒计时;
    q('countdown').textContent = countdown == null || countdown === '' ? '未记录' : (/分钟$/.test(String(countdown)) ? String(countdown) : String(countdown) + '分钟');
    q('alert').textContent = text(s.系统 && s.系统.警报);
    renderChips('supplies', s.物资 || {});
    renderChips('clues', s.线索 || [], true);
    var p = s.玩家 || {};
    q('player').textContent = text(p.称呼) + ' · ' + text(p.来历) + ' · ' + text(p.专长);
    var memo = text(s.玩家备忘 && s.玩家备忘.最新, '暂无手记');
    q('memoRead').textContent = memo;
    q('memoInput').value = memo === '暂无手记' ? '' : memo;
    suggestions = buildSuggestions(s);
    Array.from(q('actions').querySelectorAll('button')).forEach(function (button, index) {
      var item = suggestions[index];
      button.querySelector('b').textContent = item.title;
      button.querySelector('small').textContent = item.detail;
    });
    q('identity').textContent = '第 ' + messageId + ' 楼 · Swipe ' + swipeId + ' · 读取该楼自己的 MVU 快照';
    q('live').textContent = 'SNAPSHOT READY';
  }

  async function refresh() {
    try {
      var floor = getChatMessages(messageId, { include_swipes: true })[0];
      swipeId = floor ? Number(floor.swipe_id || 0) : 0;
      render(readState());
      note('读取成功；旧楼显示旧快照，编辑或 Swipe 后会重新读取。', 'ok');
    } catch (error) {
      q('live').textContent = 'UNAVAILABLE';
      note('读取失败：' + (error.message || String(error)), 'error');
    }
  }

  async function fillAction(index) {
    var item = suggestions[index];
    if (!item) return;
    var bridge = runtime();
    if (!bridge || typeof bridge.setInput !== 'function') {
      note('运行协调器不可用；请手动复制：' + item.text, 'error');
      return;
    }
    try {
      var result = await bridge.setInput(item.text);
      if (result.status === 'conflict') note(result.message + ' 行动文本：' + result.text, 'error');
      else note('行动已写入输入框，可继续编辑后发送。', 'ok');
    } catch (error) {
      note('写入输入框失败：' + (error.message || String(error)), 'error');
    }
  }

  q('actions').addEventListener('click', function (event) {
    var button = event.target.closest('button[data-index]');
    if (button) fillAction(Number(button.dataset.index));
  });

  q('saveMemo').addEventListener('click', async function () {
    var bridge = runtime();
    var value = q('memoInput').value.trim();
    if (!value) { note('先写一条手记。', 'error'); return; }
    if (!bridge || typeof bridge.writeMemo !== 'function') { note('运行协调器不可用，当前只能读取。', 'error'); return; }
    q('body').classList.add('busy');
    try {
      var result = await bridge.writeMemo(messageId, value);
      if (result && result.stat_data) render(result.stat_data);
      note('本楼手记已经等待 saveChat 并完成同楼读回。', 'ok');
    } catch (error) {
      note('保存失败：' + (error.message || String(error)), 'error');
    } finally {
      q('body').classList.remove('busy');
    }
  });

  q('retry').addEventListener('click', refresh);

  function bindEvents() {
    if (typeof eventOn !== 'function') return;
    if (typeof tavern_events === 'object') {
      [tavern_events.MESSAGE_UPDATED, tavern_events.MESSAGE_SWIPED].forEach(function (name) {
        if (!name) return;
        stops.push(eventOn(name, function (id) { if (Number(id) === messageId) refresh(); }));
      });
    }
    var bridge = runtime();
    var custom = bridge && bridge.post_write_event;
    if (custom) stops.push(eventOn(custom, function (payload) { if (Number(payload && payload.message_id) === messageId) refresh(); }));
  }

  addEventListener('pagehide', function () {
    stops.forEach(function (stop) { if (stop && typeof stop.stop === 'function') stop.stop(); });
  }, { once: true });

  (async function boot() {
    try {
      if (typeof getCurrentMessageId !== 'function' || typeof getChatMessages !== 'function') throw new Error('当前不是 Tavern Helper 消息 iframe');
      if (typeof waitGlobalInitialized !== 'function') throw new Error('缺少 waitGlobalInitialized');
      messageId = Number(getCurrentMessageId());
      if (!Number.isInteger(messageId) || messageId < 0) throw new Error('无法取得数值消息楼层');
      await Promise.race([waitGlobalInitialized('Mvu'), timeout(8000)]);
      bindEvents();
      await refresh();
    } catch (error) {
      q('live').textContent = 'BOOT FAILED';
      note('面板不可用：' + (error.message || String(error)), 'error');
    }
  })();
})();
</script>
</body>
</html>
